    for ln in lines:
        if kw.match(ln):
            if cur: blocks.append('\n'.join(cur))
            cur=[ln]
        elif cur: cur.append(ln)
    if cur: blocks.append('\n'.join(cur))
    for b in blocks:
        m = re.split(r':=|\bwhere\b', b, maxsplit=1)[0]
        if reEt.search(m):
            tot['Et']+=1; per['Et'][f.name]=per['Et'].get(f.name,0)+1
        elif reNo.search(m):
            tot['Plain']+=1; per['Plain'][f.name]=per['Plain'].get(f.name,0)+1
print("TOTALS:", tot)
for k in per: print(k, sorted(per[k].items(), key=lambda x:-x[1]))
